
from memory.database import get_connection


class ReflectionMemory:
    """Stores and retrieves lessons generated by the Reflection Agent."""

    def save_reflection(self, investigation_id, reflection):
        """Save reflection results permanently."""

        connection = get_connection()
        cursor = connection.cursor()

        try:
            cursor.execute(
                """
                SELECT id FROM investigations WHERE id = ?
                """,
                (investigation_id,)
            )

            if cursor.fetchone() is None:
                raise ValueError("Investigation not found.")

            cursor.execute(
                """
                INSERT INTO reflections
                (investigation_id, reflection)
                VALUES (?, ?)
                """,
                (investigation_id, reflection)
            )

            reflection_id = cursor.lastrowid
            connection.commit()

            return reflection_id

        finally:
            connection.close()

    def get_reflections(self, investigation_id):
        """Retrieve reflections for one investigation."""

        connection = get_connection()
        cursor = connection.cursor()

        cursor.execute(
            """
            SELECT * FROM reflections
            WHERE investigation_id = ?
            ORDER BY created_at DESC
            """,
            (investigation_id,)
        )

        results = cursor.fetchall()
        connection.close()

        return [dict(row) for row in results]

    def get_all_reflections(self):
        """Retrieve all stored reflections."""

        connection = get_connection()
        cursor = connection.cursor()

        cursor.execute(
            """
            SELECT * FROM reflections
            ORDER BY created_at DESC
            """
        )

        results = cursor.fetchall()
        connection.close()

        return [dict(row) for row in results]
